//! Complete Submerge sources retain viewed-set partitioning and optional scope.
use ironsmith::{CardDefinition, Effect, GameState, ObjectId, PlayerId, Zone};
use ironsmith::decision::{DecisionMaker, SelectFirstDecisionMaker};
use ironsmith::effects::{EffectContext, ResolvedTarget, execute_effect};
use ironsmith_compiled_artifact::CompiledCardArtifact;
const A:PlayerId=PlayerId(0);const B:PlayerId=PlayerId(1);
fn definitions(name:&str)->[CardDefinition;2]{let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/msem-linked-face-down.json")).unwrap();let card=fixture["mechanics"][0]["representative_cards"].as_array().unwrap().iter().find(|card|card["name"]==name).unwrap();assert_eq!(card["rewrite_status"],"frontend_materialized_unverified");let(result,loss)=ironsmith_compiler::parse_loss::capture(||ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact(name,card["executable_text"].as_str().unwrap(),false)));assert!(!loss.is_lossy(),"{name}: {}",loss.reasons_text());let(artifact,direct)=result.unwrap();let decoded=CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();assert_eq!(artifact,decoded);[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&decoded).unwrap()]}
struct Choices{accept:bool,choose:ObjectId}
impl DecisionMaker for Choices{
fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{self.accept}
fn decide_objects(&mut self,game:&GameState,ctx:&ironsmith::decisions::context::SelectObjectsContext)->Vec<ObjectId>{if ctx.candidates.iter().any(|candidate|candidate.legal&&candidate.id==self.choose){vec![self.choose]}else{SelectFirstDecisionMaker.decide_objects(game,ctx)}}
}
fn body()->CardDefinition{ironsmith_compiler_runtime::compile_to_runtime_definition("Choice witness","Mana cost: {G}\nType: Creature — Elf\nPower/Toughness: 4/5",false).unwrap()}
fn apply(game:&mut GameState,source:ObjectId,definition:&CardDefinition,dm:&mut dyn DecisionMaker,targets:Vec<ResolvedTarget>){let effects=definition.spell_effect.as_ref().unwrap().all_effects_owned();execute_effect(game,&Effect::new(ironsmith::effects::SequenceEffect::new(effects)),&mut EffectContext::new_default(source,A).with_targets(targets).with_decision_maker(dm)).unwrap();}
#[test]
fn actual_optional_hand_action_declines_the_whole_exile_return_status_program(){
for definition in definitions("Into the Flood Realm"){for accept in [false,true]{let mut game=GameState::new(vec!["A".into(),"B".into()],20);let source=game.create_object_from_definition(&definition,A,Zone::Stack);let witness=body();let old_hand=game.create_object_from_definition(&witness,A,Zone::Hand);let stable=game.object(old_hand).unwrap().stable_id;let sentinel=game.create_object_from_definition(&witness,A,Zone::Library);for _ in 0..3{game.create_object_from_definition(&witness,A,Zone::Library);}let mut dm=Choices{accept,choose:old_hand};apply(&mut game,source,&definition,&mut dm,vec![]);let current=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.object(current).unwrap().zone,if accept{Zone::Battlefield}else{Zone::Hand});assert_eq!(game.player(A).unwrap().hand.len(),if accept{3}else{4});assert_eq!(game.battlefield.len(),usize::from(accept));assert_eq!(game.object(sentinel).unwrap().zone,Zone::Library);if accept{assert!(game.is_face_down(current));assert!(game.has_custom_status(current,"submerged"));assert!(!game.has_printed_cost_turn_face_up_permission(current));}}}
}
#[test]
fn actual_viewed_partition_submerges_only_the_other_of_the_original_two_cards(){
for definition in definitions("Beckon from the Depths"){let mut game=GameState::new(vec!["A".into(),"B".into()],20);let source=game.create_object_from_definition(&definition,A,Zone::Stack);let witness=body();let sentinel=game.create_object_from_definition(&witness,A,Zone::Library);let other=game.create_object_from_definition(&witness,A,Zone::Library);let other_stable=game.object(other).unwrap().stable_id;let take=game.create_object_from_definition(&witness,A,Zone::Library);let take_stable=game.object(take).unwrap().stable_id;let mut dm=Choices{accept:true,choose:take};apply(&mut game,source,&definition,&mut dm,vec![]);let hand=game.find_object_by_stable_id(take_stable).unwrap();let submerged=game.find_object_by_stable_id(other_stable).unwrap();assert_eq!(game.object(hand).unwrap().zone,Zone::Hand);assert_eq!(game.object(submerged).unwrap().zone,Zone::Battlefield);assert!(game.is_face_down(submerged));assert_eq!(game.calculated_power(submerged),Some(2));assert_eq!(game.object(sentinel).unwrap().zone,Zone::Library);assert_eq!(game.player(A).unwrap().library.len(),1);}
}
#[test]
fn actual_spell_target_exiles_its_stack_entry_and_returns_the_card_under_its_owner(){
for definition in definitions("Lost Among the Lilies"){let mut game=GameState::new(vec!["A".into(),"B".into()],20);let source=game.create_object_from_definition(&definition,A,Zone::Stack);let spell=ironsmith_compiler_runtime::compile_to_runtime_definition("Target spell witness","Mana cost: {U}\nType: Instant\nYou gain 1 life.",false).unwrap();let target=game.create_object_from_definition(&spell,B,Zone::Stack);let stable=game.object(target).unwrap().stable_id;game.push_to_stack(ironsmith::game_state::StackEntry::new(target,B));let mut dm=Choices{accept:true,choose:target};apply(&mut game,source,&definition,&mut dm,vec![ResolvedTarget::Object(target)]);let returned=game.find_object_by_stable_id(stable).unwrap();assert!(game.stack.is_empty());assert_eq!(game.object(returned).unwrap().zone,Zone::Battlefield);assert_eq!(game.controller_of_id(returned),Some(B));assert!(game.is_face_down(returned));assert!(!game.has_printed_cost_turn_face_up_permission(returned));}
}

#[test]
fn actual_mass_graveyard_action_processes_every_card_with_its_own_owner(){
for definition in definitions("Rise from the Depths"){let mut game=GameState::new(vec!["A".into(),"B".into()],20);let source=game.create_object_from_definition(&definition,A,Zone::Stack);let witness=body();let cards:Vec<_>=[A,B].into_iter().map(|owner|{let id=game.create_object_from_definition(&witness,owner,Zone::Graveyard);(game.object(id).unwrap().stable_id,owner)}).collect();let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Unselected graveyard artifact","Type: Artifact",false).unwrap();let untouched=game.create_object_from_definition(&artifact,B,Zone::Graveyard);let mut dm=Choices{accept:true,choose:source};apply(&mut game,source,&definition,&mut dm,vec![]);for(stable,owner)in cards{let id=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.object(id).unwrap().zone,Zone::Battlefield);assert_eq!(game.controller_of_id(id),Some(owner));assert!(game.is_face_down(id));assert!(game.has_custom_status(id,"submerged"));assert!(!game.has_printed_cost_turn_face_up_permission(id));}assert_eq!(game.object(untouched).unwrap().zone,Zone::Graveyard);}
}
struct All;
impl DecisionMaker for All{
fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{true}
fn decide_objects(&mut self,_:&GameState,ctx:&ironsmith::decisions::context::SelectObjectsContext)->Vec<ObjectId>{ctx.candidates.iter().filter(|candidate|candidate.legal).take(ctx.max.unwrap_or(usize::MAX)).map(|candidate|candidate.id).collect()}
}
#[test]
fn actual_coax_loop_keeps_the_single_delayed_instruction_outside_even_when_the_loop_is_empty(){
for definition in definitions("Coax Under"){for count in [0,2]{let mut game=GameState::new(vec!["A".into(),"B".into()],20);let source=game.create_object_from_definition(&definition,A,Zone::Stack);let witness=body();let cards:Vec<_>=(0..count).map(|_|{let id=game.create_object_from_definition(&witness,A,Zone::Battlefield);game.object(id).unwrap().stable_id}).collect();let opponent=game.create_object_from_definition(&witness,B,Zone::Battlefield);game.set_face_down(opponent);apply(&mut game,source,&definition,&mut All,vec![]);assert_eq!(game.effect_store.delayed_triggers.len(),1,"one sourced sibling delay remains outside the entire compound macro");for stable in &cards{assert!(game.is_face_down(game.find_object_by_stable_id(*stable).unwrap()));}game.queue_trigger_event(Default::default(),ironsmith::triggers::TriggerEvent::new(ironsmith::events::BeginningOfEndStepEvent::new(A),Default::default()));let mut queue=ironsmith::triggers::TriggerQueue::new();ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut All).unwrap();ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game,&mut queue,&mut All).unwrap();assert_eq!(game.stack.len(),1);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut All).unwrap();for stable in cards{let id=game.find_object_by_stable_id(stable).unwrap();assert!(!game.is_face_down(id));assert!(!game.has_custom_status(id,"submerged"));}assert!(game.is_face_down(opponent),"the delayed instruction only affects creatures its controller controls");}}
}
